using MediatR; using Microsoft.AspNetCore.Http; using Microsoft.AspNetCore.Routing; namespace JTradeERP.Application.Features.MasterData.Categories.ActivateCategory; public static class ActivateCategoryEndpoint { public static void Map(IEndpointRouteBuilder e)=>e.MapPost("/categories/{id:guid}/activate",async(Guid id,ISender s,CancellationToken ct)=>Results.Ok(await s.Send(new ActivateCategoryCommand(id),ct))); }
